#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

void dfs(const vector<vector<int>>& graph, int node, vector<bool>& visited, vector<int>& order) {
    visited[node] = true;
    for (int neighbor : graph[node])
        if (!visited[neighbor]) dfs(graph, neighbor, visited, order);
    order.push_back(node);
}

vector<int> topoSort(const vector<vector<int>>& graph) {
    vector<bool> visited(graph.size());
    vector<int> order;
    for (int i = 0; i < graph.size(); i++)
        if (!visited[i]) dfs(graph, i, visited, order);
    reverse(order.begin(), order.end());
    return order;
}

int main() {
    vector<vector<int>> graph = {{1,2},{3},{3},{}};
    auto order = topoSort(graph);
    for (int v : order) cout << v << " ";
    cout << endl;
    return 0;
}
